  "dash.syncCodexSubagentDefaultsHint": {
    "de": "Eingeschaltet wird die Wahl von oben in Codex' eigene Konfiguration geschrieben, sodass auch neue Aufgaben mit diesem Modell starten. Ausgeschaltet wird sie nur hier gemerkt. Wirksam beim nächsten Sync oder Neustart; deine selbst geschriebenen [agents]-Einstellungen bleiben unberührt.",
    "fr": "Si cette option est activée, le choix ci-dessus est inscrit dans la configuration de Codex afin que les nouvelles tâches commencent aussi avec ce modèle. Si elle est désactivée, il n’est mémorisé qu’ici. Il prend effet à la prochaine synchronisation ou au prochain redémarrage, sans modifier vos paramètres [agents] saisis manuellement.",
    "ko": "켜면 위에서 고른 모델이 Codex 설정 파일에 저장돼, 새로 시작하는 작업도 처음부터 그 모델을 씁니다. 끄면 여기서만 기억합니다. 반영은 다음 동기화나 재시작 때이고, 직접 적어둔 [agents] 설정은 그대로 둡니다.",
    "zh": "打开后，上面选的模型会写进 Codex 自己的配置，新任务一开始也用它。关闭则只在这里记住。下次同步或重启后生效，你手写的 [agents] 设置不会被改动。",
    "zh-TW": "預設關閉。當 Benes 管理 Codex 路由時，同步或重啟會將所選模型和推理強度應用為新 Codex 任務的原生 Codex [agents] 預設值。此設定本身不會觸發委託；現有的使用者自有 [agents] 預設值會保留而不會被覆蓋。",
    "ru": "Если включено, выбранная выше модель записывается в собственную конфигурацию Codex, и новые задачи тоже начинаются с неё. Если выключено, выбор запоминается только здесь. Применится при следующей синхронизации или перезапуске, а ваши настройки [agents] останутся нетронутыми.",
    "ja": "オンにすると、上で選んだモデルが Codex 自身の設定にも保存され、新しいタスクも最初からそのモデルを使います。オフならここだけで記憶します。反映は次回の同期または再起動時で、自分で書いた [agents] 設定はそのまま残ります。",
    "tr": "Açık olduğunda, yukarıdaki seçim Codex'in kendi yapılandırmasına yazılır.",
  },
  "dash.multiAgentGuidance": {
    "de": "Codex sagen, wie Arbeit aufgeteilt wird",
    "fr": "Indiquer à Codex comment répartir le travail",
    "ko": "일 나누는 방법 알려주기",
    "zh": "告诉 Codex 怎么分工",
    "zh-TW": "Benes 多代理指引",
    "ru": "Подсказывать, как делить работу",
    "ja": "作業の分け方を伝える",
    "tr": "Codex'e işi nasıl böleceğini söyle",
  },
  "dash.multiAgentGuidanceHint": {
    "de": "Schickt Codex eine kurze Notiz, wie Arbeit an Sub-Agenten übergeben werden soll. Auf v2 nennt sie die verfügbaren Modelle und das bevorzugte; auf v1 wirkt sie nur bei Reasoning-Effort max oder ultra. Ausgeschaltet wird keine Notiz angehängt.",
    "fr": "Envoie une brève note indiquant à Codex comment confier le travail aux sous-agents. En v2, elle précise les modèles utilisables et celui à privilégier ; en v1, elle ne s’applique qu’avec un effort de raisonnement maximal ou ultra. Si cette option est désactivée, aucune note n’est ajoutée.",
    "ko": "Codex에게 \"일을 이렇게 나눠 맡기면 된다\"는 짧은 쪽지를 붙여 보냅니다. v2에서는 쓸 수 있는 모델 목록과 우선 모델을 알려주고, v1에서는 추론 강도가 max나 ultra일 때만 동작합니다. 끄면 아무 쪽지도 붙지 않습니다.",
    "zh": "给 Codex 附上一张短便条，说明怎么把活分给子代理。v2 会告诉它可用的模型和优先模型；v1 只在推理强度为 max 或 ultra 时才起作用。关闭则不附任何便条。",
    "zh-TW": "新增由 Benes 編寫的委託指引。它與上方的原生 Codex 預設值相互獨立，不會更改 v1/v2 介面、子代理清單、路由或 effort 上限。",
    "ru": "Отправляет Codex короткую записку о том, как передавать работу подагентам. На v2 она называет доступные модели и предпочтительную; на v1 работает только при усилии рассуждения max или ultra. Если выключено, записка не добавляется.",
    "ja": "「作業はこう分けて任せる」という短いメモを Codex に送ります。v2 では使えるモデルと優先モデルを伝え、v1 では推論強度が max か ultra のときだけ働きます。オフならメモは付きません。",
    "tr": "Codex'e işleri alt ajanlara nasıl devredeceğini söyleyen kısa bir not gönderir.",
  },
