  "prov.openaiPoolDesc": {
    "de": "Standard. Wechselt mit Affinität, Kontingent, Abklingzeit und Ausfallsicherung zwischen Hauptanmeldung und hinzugefügten Konten.",
    "fr": "Par défaut. Alterne entre la connexion principale et les comptes ajoutés selon l’affinité, le quota, le délai de récupération et le repli.",
    "ko": "기본값입니다. 메인 로그인과 추가 계정을 친화도, 할당량, 대기 시간, 장애 조치에 따라 순환합니다.",
    "zh": "默认模式。根据会话关联、额度、冷却时间和故障转移，在主登录与已添加账户之间轮换。",
    "zh-TW": "預設模式。根據會話關聯、額度、冷卻時間和容錯移轉，在主登入與已新增帳號之間輪換。",
    "ru": "По умолчанию. Ротация основного входа и добавленных аккаунтов с учётом привязки, квот, периодов ожидания и отказоустойчивого переключения (failover).",
    "ja": "デフォルト。アフィニティ、クォータ、クールダウン、フェイルオーバーを使ってメインログインと追加アカウントをローテーションします。",
    "tr": "Varsayılan. Ana girişi ve eklenen hesapları havuzda döndürür.",
  },
  "prov.openaiDirectDesc": {
    "de": "Verwendet nur die aktuelle primäre Codex-Anmeldung. Gespeicherte Pool-Konten werden weder gelesen noch gewechselt.",
    "fr": "Utilise uniquement la connexion Codex actuelle ou principale. Les comptes du groupe enregistrés ne sont ni lus ni utilisés en alternance.",
    "ko": "현재 메인 Codex 로그인만 사용합니다. 저장된 풀 계정은 읽거나 순환하지 않습니다.",
    "zh": "仅使用当前主 Codex 登录。不会读取或轮换已存储的账户池账号。",
    "zh-TW": "僅使用當前主 Codex 登入。不會讀取或輪換已儲存的帳號池帳號。",
    "ru": "Используется только текущий/основной вход Codex. Сохранённые аккаунты пула не читаются и не ротируются.",
    "ja": "現在/メインの Codex ログインのみを使用します。保存されたプールアカウントは読み込まれずローテーションもされません。",
    "tr": "Yalnızca ana Codex girişini kullanır.",
  },
