  "storage.cleanup.help": {
    "de": "Entfernt die ältesten archivierten Sitzungen nach Prozentsatz. Aktive Sitzungen werden nie angefasst. Standard ist Quarantäne — Dateien wandern nach CODEX_HOME/.trash.",
    "fr": "Supprimez un pourcentage des sessions archivées les plus anciennes. Les sessions actives ne sont jamais touchées. La quarantaine est le mode par défaut : les fichiers sont déplacés vers CODEX_HOME/.trash.",
    "ko": "가장 오래된 보관 세션을 비율로 제거합니다. 활성 세션은 건드리지 않습니다. 기본은 격리이며 파일은 CODEX_HOME/.trash로 이동합니다.",
    "zh": "按百分比移除最旧的归档会话。不会触碰活动会话。默认隔离——文件移至 CODEX_HOME/.trash。",
    "zh-TW": "按百分比移除最舊的歸檔會話。不會觸碰活動會話。預設隔離——檔案移至 CODEX_HOME/.trash。",
    "ru": "Удаляет самые старые архивные сессии по проценту. Активные сессии не затрагиваются. По умолчанию — карантин: файлы перемещаются в CODEX_HOME/.trash.",
    "ja": "古いアーカイブセッションを割合で削除します。アクティブセッションには触れません。既定は隔離で、ファイルは CODEX_HOME/.trash へ移動します。",
    "tr": "En eski arşivlenmiş oturumları yüzdeye göre kaldırın.",
  },
