  "integrations.native.error.orphanedMarker": {
    "de": "{path} enthält eine benes-Startmarkierung, aber keine Endmarkierung. Die Datei wurde nicht geändert, weil das Ende des Blocks nicht sicher bestimmt werden kann.",
    "fr": "{path} contient un marqueur de début benes, mais aucun marqueur de fin. Le fichier est resté inchangé, car benes ne peut pas déterminer où se termine son bloc.",
    "ko": "{path}에 benes 시작 표시는 있는데 끝 표시가 없습니다. 어디까지가 우리 블록인지 확신할 수 없어 파일을 건드리지 않았습니다.",
    "zh": "{path} 中有 benes 开始标记，但没有结束标记。由于无法确定该区块的结束位置，因此未修改文件。",
    "zh-TW": "{path} 有 benes 開始標記但沒有結束標記。由於 benes 無法判斷其區塊的結束位置，因此未變更檔案。",
    "ru": "В {path} есть начальная метка benes, но нет конечной. Файл не изменён, потому что невозможно надёжно определить конец блока.",
    "ja": "{path} に benes の開始マーカーはありますが、終了マーカーがありません。ブロックの終端を特定できないため、ファイルは変更していません。",
    "tr": "{path} bir benes başlangıç işaretine sahip ancak bitiş işareti yok. benes bloğunun nerede bittiğini belirleyemediği için dosya değiştirilmeden bırakıldı.",
  },
