  "integrations.error.nonLoopback": {
    "de": "{client} erreicht nur einen Proxy auf localhost. In seiner Konfiguration ist kein Platz für den Header, den eine Remote-Bindung verlangt — von Hand geschrieben hilft es also ebenso wenig. Ermöglichen Sie stattdessen Loopback-Zugriff, etwa über einen Tunnel oder lokalen Forwarder.",
    "fr": "{client} ne peut atteindre qu’un proxy sur localhost — sa configuration ne permet pas d’ajouter l’en-tête d’admission requis par une liaison distante ; l’écrire manuellement ne servirait donc à rien. Donnez-lui plutôt un accès par bouclage, via un tunnel ou un redirecteur local.",
    "ko": "{client}은(는) localhost 프록시에만 연결할 수 있습니다. 원격 바인드에 필요한 인증 헤더를 넣을 자리가 설정 파일에 없어 직접 작성해도 마찬가지입니다. 터널이나 로컬 포워더로 loopback 경로를 열어주세요.",
    "zh": "{client} 只能连接 localhost 上的代理：其配置没有位置放置远程绑定所需的准入标头，手动编写同样无效。请改用隧道或本地转发器提供 loopback 访问。",
    "zh-TW": "{client} 只能連線到 localhost 上的 proxy——其設定沒有位置可放入遠端繫結所需的准入標頭，手動撰寫也不會有幫助。請改以隧道或本機轉發器提供 loopback 存取。",
    "ru": "{client} может обращаться только к прокси на localhost: в его конфигурации негде разместить заголовок, который требуется при удалённой привязке, поэтому ручная настройка тоже не поможет. Обеспечьте доступ через loopback — туннелем или локальным форвардером.",
    "ja": "{client} は localhost のプロキシにしか接続できません。リモートバインドに必要な認証ヘッダーを置く場所が設定ファイルになく、手動で書いても同じです。トンネルやローカルフォワーダーで loopback 経路を用意してください。",
    "tr": "{client} istemcisi geri döngü (loopback) dışında bir adreste. Yerel entegrasyonlar yalnızca loopback (127.0.0.1 veya ::1) üzerinden düzenlenebilir. Bir API anahtarı ayarlayın veya yerel erişim kullanın.",
  },
