  "codexAuth.switchTitle": {
    "de": "Aktives Konto wechseln?",
    "fr": "Changer de compte actif ?",
    "ko": "활성 계정을 변경하시겠습니까?",
    "zh": "切换活跃账号？",
    "zh-TW": "切換活躍帳號？",
    "ru": "Сменить активный аккаунт?",
    "ja": "アクティブアカウントを切り替えますか?",
    "tr": "Aktif hesap değiştirilsin mi?",
  },
  "codexAuth.switchDesc": {
    "de": "Wird sofort wirksam. Bereits laufende Anfragen behalten ihr Konto; alles andere wechselt zu diesem Konto, wobei Konten mit derselben Auswahlreihenfolge sich weiterhin abwechseln.",
    "fr": "Prend effet immédiatement. Les fils liés à un compte et les requêtes déjà en cours conservent le compte capturé ; les requêtes nouvelles ou non liées utilisent le niveau d’ordre du compte sélectionné, et les comptes de même ordre continuent d’alterner.",
    "ko": "즉시 적용됩니다. 계정에 바인딩된 기존 스레드와 이미 진행 중인 요청은 기존 계정을 유지하고, 새 요청이나 바인딩 없는 요청은 선택한 계정의 순서 티어를 사용합니다. 같은 선택 순서의 계정은 계속 번갈아 사용됩니다.",
    "zh": "立即生效。已在进行中的请求保留原账号，其余都会切换到此账号；不过选择顺序相同的账号仍会轮换使用。",
    "zh-TW": "從現有和新 Codex 會話的下一次請求開始生效。進行中的請求保留原帳號。",
    "ru": "Применяется сразу. Существующие привязанные к аккаунту потоки и уже выполняющиеся запросы сохраняют прежний аккаунт; новые или непривязанные запросы используют порядковый уровень выбранного аккаунта. Аккаунты с тем же порядком выбора продолжают чередоваться.",
    "ja": "すぐに反映されます。アカウントに紐付いた既存スレッドと処理中のリクエストは現在のアカウントを維持し、新規または未紐付けのリクエストは選択したアカウントの順序ティアを使います。同じ選択順序のアカウントは引き続き交代で使われます。",
    "tr": "Anında yürürlüğe girer. Mevcut hesaba bağlı iş parçacıkları ve işlenmekte olan istekler yakalanan hesaplarını korur; yeni veya bağımsız istekler seçilen hesabın sıra kademesini kullanır ve aynı seçim sırasındaki hesaplar sırayla görev almaya devam eder.",
  },
  "codexAuth.cacheWarning": {
    "de": "Prompt-Cache wird beim Kontowechsel zurückgesetzt. Neue Sitzung startet mit leerem Cache.",
    "fr": "Le cache des prompts est réinitialisé lors d’un changement de compte. La nouvelle session démarre avec un cache vide.",
    "ko": "계정 전환 시 프롬프트 캐시가 초기화됩니다.",
    "zh": "切换账号会重置提示缓存。新会话从空缓存开始。",
    "zh-TW": "切換帳號會重設提示快取。新會話從空快取開始。",
    "ru": "Кэш промптов сбрасывается при смене аккаунта. Новая сессия начнётся с пустым кэшем.",
    "ja": "アカウント切り替えでプロンプトキャッシュはリセットされます。新規セッションは空のキャッシュで開始します。",
    "tr": "Hesap değiştirildiğinde önbellek sıfırlanır.",
  },
