  "accountPool.strategyHintQuota": {
    "de": "Kontingent kann eine bestehende Aufgabe bei ihrer nächsten Anfrage neu binden, nachdem die Nutzungsschwelle überschritten wurde.",
    "fr": "La stratégie Quota peut également relier une tâche existante à un autre compte lors de sa requête suivante, une fois le seuil d’utilisation franchi.",
    "ko": "할당량 전략은 사용량 임계값을 넘으면 기존 작업의 다음 요청도 다른 계정에 다시 바인딩할 수 있습니다.",
    "zh": "配额策略在超过用量阈值后，也可以在现有任务的下一次请求中重新绑定账号。",
    "zh-TW": "配額也可以在跨越用量閾值後，於下次請求時重新綁定現有任務。",
    "ru": "Quota может перепривязать существующую задачу при следующем запросе после превышения порога использования.",
    "ja": "クォータ戦略は使用量しきい値を超えると、既存タスクの次のリクエストも別アカウントへ再紐付けできます。",
    "tr": "Kota kullanımı eşik aşıldığında hesabı değiştirebilir.",
  },
  "accountPool.strategyHintRoundRobin": {
    "de": "Round-Robin rotiert nur Aufgaben ohne aktive Bindung; die Nutzungsschwelle ändert die normale Rotation nicht.",
    "fr": "La rotation ne concerne que les tâches sans liaison active ; le seuil d’utilisation ne modifie pas la rotation normale.",
    "ko": "라운드로빈은 현재 바인딩이 없는 작업만 순환하며, 사용량 임계값은 기본 순환에 영향을 주지 않습니다.",
    "zh": "轮询只轮换没有有效绑定的任务；用量阈值不会改变正常轮换。",
    "zh-TW": "輪詢僅輪換沒有有效綁定的任務；用量閾值不會改變正常輪換。",
    "ru": "Round-robin ротирует только задачи без действующей привязки; порог использования не меняет обычную ротацию.",
    "ja": "ラウンドロビンは有効な紐付けがないタスクだけをローテーションし、使用量しきい値は通常のローテーションを変えません。",
    "tr": "Round-robin yalnızca canlı bir hesap bağı olmayan yeni/bağımsız görevleri döndürür; mevcut görevler bağlı kalabilir ve kullanım eşiği normal rotasyonu değiştirmez.",
  },
  "accountPool.strategyHintFillFirst": {
    "de": "Fill-first nutzt die Schwelle als Entleerungspunkt für ungebundene Aufgaben; gesunde gebundene Aufgaben behalten ihre Affinität.",
    "fr": "Le remplissage prioritaire utilise le seuil comme point d’épuisement pour les tâches non liées ; les tâches liées saines conservent leur affinité.",
    "ko": "필 퍼스트는 임계값을 바인딩 없는 작업의 소진 기준으로 사용하며, 정상적인 바인딩 작업은 어피니티를 유지합니다.",
    "zh": "填满优先把阈值用作未绑定任务的耗尽点；健康的已绑定任务保持亲和性。",
    "zh-TW": "優先填滿將閾值用作未綁定任務的耗盡點；健康的已綁定任務保持親和性。",
    "ru": "Fill-first использует порог как точку исчерпания для непривязанных задач; здоровые привязанные задачи сохраняют affinity.",
    "ja": "フィルファーストはしきい値を未紐付けタスクの使い切り基準として使用し、正常な紐付け済みタスクは親和性を維持します。",
    "tr": "İlk doldurma eşiği boşaltma noktası olarak kullanır.",
  },
  "accountPool.strategyHintResetWindow": {
    "de": "Reset-Fenster ordnet geeignete Konten nach dem Reset des maßgeblichen Kontingentfensters. Fehlende oder veraltete Reset-Daten fallen auf die Kontingentreihenfolge zurück. Gebundene Aufgaben behalten ihre Affinität.",
    "fr": "La fenêtre de reset classe les comptes éligibles selon la fin de leur fenêtre de quota déterminante. Une preuve manquante ou périmée revient au classement par quota. Les tâches liées conservent leur affinité.",
    "ko": "리셋 윈도우는 지배 할당량 창의 리셋 시각으로 적격 계정을 정렬합니다. 없거나 오래된 리셋 증거는 할당량 순위로 돌아갑니다. 바인딩된 작업은 어피니티를 유지합니다.",
    "zh": "重置窗口按主导配额窗口的重置时间排列合格账号。缺失或过期的重置证据回退到配额排序。已绑定任务保持亲和性。",
    "zh-TW": "重設視窗依主導配額視窗的重設時間排列合格帳號。缺失或過期的重設證據回退到配額排序。已綁定任務保持親和性。",
    "ru": "Окно сброса ранжирует подходящие аккаунты по сбросу определяющего окна квоты. Отсутствующие или устаревшие данные возвращаются к ранжированию по квоте. Привязанные задачи сохраняют affinity.",
    "ja": "リセット窓は、支配的なクォータ窓のリセット時刻で適格アカウントを並べます。欠損や古いリセット証拠はクォータ順位に戻します。紐付け済みタスクは親和性を維持します。",
    "tr": "Sıfırlama penceresi uygun hesapları yöneten kota penceresinin sıfırlanma zamanına göre sıralar. Eksik veya bayat kanıt kota sıralamasına döner. Bağlı görevler affinity korur.",
  },
