  "accountPool.stickyLimitHelp": {
    "de": "So viele neue/ungebundene Aufgaben dem gewählten Konto zuweisen, bevor weitergeschaltet wird; gezählt wird bei der Bindung, nicht nach einem Upstream-Erfolg.",
    "fr": "Conservez le compte sélectionné pour ce nombre d’affectations de tâches nouvelles/non liées avant de passer au suivant ; le compteur augmente lorsque la tâche est liée, et non après la réussite en amont.",
    "ko": "다음 계정으로 넘어가기 전에 이 횟수의 새 작업/바인딩 없는 작업을 선택 계정에 배정합니다. 카운터는 업스트림 성공 후가 아니라 작업을 바인딩할 때 증가합니다.",
    "zh": "在推进到下一个账号之前，为所选账号分配这么多次新建/未绑定任务；计数在任务绑定时增加，而不是在上游成功后增加。",
    "zh-TW": "在推進到下一個帳號之前，將所選帳號保留這麼多次成功的新會話繫結。",
    "ru": "Назначить выбранному аккаунту столько новых/непривязанных задач перед переходом дальше; счётчик растёт при привязке задачи, а не после успеха upstream.",
    "ja": "次へ進む前に、この回数の新規/未紐付けタスクを選択アカウントへ割り当てます。カウンターは上流の成功後ではなく、タスクを紐付けた時点で増えます。",
    "tr": "Seçilen hesabı bu kadar yeni atama boyunca tutun.",
  },
